# owner: platform
"""Short absence notices for parents."""

from typing import List

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date


def check_owner(student: Student, marks: List[Mark]):
    """Refuse marks that belong to another student."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id!r}"
            )


def describe(days: List[date]) -> str:
    """Count the days and list them, oldest first."""
    noun = "day" if len(days) == 1 else "days"
    dates = ", ".join(day.isoformat() for day in days)
    return f"{len(days)} {noun} of school: {dates}"


def compose(student: Student, days: List[date]) -> str:
    """Write the notice text for a list of days."""
    if not days:
        raise ValueError("no absences to write about")
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {describe(days)}."


def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    """Build a notice naming the days a student missed."""
    check_owner(student, marks)
    return compose(student, days_missed(marks))
